sketch.css:
.fc{box-sizing:border-box;width:100%;height:100%;display:flex;flex-direction:column;gap:6px;padding:10px 12px;background:var(--window);color:var(--text);font:13px/1.4 "Segoe UI",system-ui,sans-serif;overflow:hidden}
.fc *{box-sizing:border-box}
.head{display:flex;justify-content:space-between;align-items:baseline;gap:10px}
.titles{display:flex;align-items:baseline;gap:6px;min-width:0}
.title{font-weight:600;font-size:13.5px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.unit{color:var(--muted);font-size:12px;white-space:nowrap}
.front{display:flex;align-items:baseline;gap:6px;white-space:nowrap}
.flabel{color:var(--muted);font-size:12px}
.fvalue{font-size:20px;font-weight:700;letter-spacing:-.02em;font-variant-numeric:tabular-nums}
.change{font-size:12px;font-weight:600;padding:1px 7px;border-radius:10px}
.change.up{color:var(--positive);background:color-mix(in srgb,var(--positive) 14%,transparent)}
.change.down{color:var(--negative);background:color-mix(in srgb,var(--negative) 14%,transparent)}
.chart{flex:1;min-height:90px;position:relative}
.plot{position:absolute;inset:0}
.plot svg{display:block;width:100%;height:100%;overflow:visible}
.grid{stroke:var(--border);stroke-width:1}
.axis{fill:var(--muted);font-size:11px;font-family:inherit}
.axis.x{text-anchor:middle}
.axis.y{text-anchor:end}
.vol{fill:color-mix(in srgb,var(--accent) 14%,transparent)}
.prior{fill:none;stroke:var(--muted);stroke-width:1.5;stroke-dasharray:4 3;opacity:.8}
.line{fill:none;stroke:var(--accent);stroke-width:2.2;stroke-linejoin:round;stroke-linecap:round}
.area{fill:color-mix(in srgb,var(--accent) 7%,transparent)}
.dot{fill:var(--window);stroke:var(--accent);stroke-width:2}
.hedge{stroke:var(--positive);stroke-width:3;stroke-linecap:round}
.month{fill:transparent;cursor:pointer}
.month:hover{fill:var(--hover);fill-opacity:.55}
.month.selected{fill:color-mix(in srgb,var(--accent) 10%,transparent)}
.dot.selected{fill:var(--accent);r:5}
.tip{position:absolute;pointer-events:none;display:none;min-width:150px;background:var(--window);border:1px solid var(--border);border-radius:8px;box-shadow:0 4px 14px rgba(20,20,50,.14);padding:7px 10px;font-size:12px;z-index:2}
.tip .tm{font-weight:600;margin-bottom:3px}
.tip .tr{display:flex;justify-content:space-between;gap:14px;color:var(--muted)}
.tip .tr b{color:var(--text);font-weight:600;font-variant-numeric:tabular-nums}
.legend{display:flex;flex-wrap:wrap;gap:4px 14px;color:var(--muted);font-size:11.5px}
.legend .k{display:inline-flex;align-items:center;gap:5px}
.legend i{display:inline-block;width:14px;height:0;border-top:2px solid var(--accent)}
.legend i.pr{border-top:2px dashed var(--muted)}
.legend i.hp{border-top:3px solid var(--positive);width:10px;border-radius:2px}
.legend i.hv{height:9px;width:9px;border:0;background:color-mix(in srgb,var(--accent) 22%,transparent);border-radius:2px}
.empty{color:var(--muted);font-size:12px;padding:30px 0;text-align:center}

sketch.js:
function render(root, props, fire) {
  const esc = s => String(s == null ? '' : s).replace(/[&<>"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
  const dec = props.decimals == null ? 3 : props.decimals;
  const num = v => (v == null || isNaN(v)) ? '—' : (+v).toFixed(dec);
  const vol = v => (v == null || isNaN(v)) ? '—' : Math.round(+v).toLocaleString('en-US');
  const has = v => v != null && v !== '' && !isNaN(+v) && +v !== 0;
  const pts = (props.points || []).filter(p => p && p.month != null && !isNaN(+p.price));
  const showPrior = props.showPrior !== false;

  root.querySelector('.title').textContent = props.title || '';
  root.querySelector('.unit').textContent = props.unit || '';

  // front month
  const f = pts[0];
  const fl = root.querySelector('.flabel'), fv = root.querySelector('.fvalue'), ch = root.querySelector('.change');
  if (f) {
    fl.textContent = f.month;
    fv.textContent = num(f.price);
    if (has(f.priorPrice)) {
      const c = f.price - f.priorPrice;
      ch.style.display = '';
      ch.className = 'change ' + (c >= 0 ? 'up' : 'down');
      ch.textContent = (c >= 0 ? '▲ ' : '▼ ') + Math.abs(c).toFixed(dec);
    } else ch.style.display = 'none';
  } else { fl.textContent = ''; fv.textContent = ''; ch.style.display = 'none'; }

  const plot = root.querySelector('.plot'), tip = root.querySelector('.tip');
  const legend = root.querySelector('.legend');
  tip.style.display = 'none';
  if (pts.length < 2) { plot.innerHTML = '<div class="empty">No curve</div>'; legend.innerHTML = ''; return; }

  // geometry in real pixels so text and dots never stretch
  const W = Math.max(200, plot.clientWidth || 520), H = Math.max(80, plot.clientHeight || 200);
  const L = 38, R = 8, T = 6, B = 18;
  const pw = W - L - R, ph = H - T - B;
  const vals = [];
  pts.forEach(p => { vals.push(+p.price); if (showPrior && has(p.priorPrice)) vals.push(+p.priorPrice); if (has(p.hedgedPrice)) vals.push(+p.hedgedPrice); });
  let lo = Math.min.apply(null, vals), hi = Math.max.apply(null, vals);
  const span = (hi - lo) || 1; lo -= span * .12; hi += span * .08;
  const maxVol = Math.max.apply(null, pts.map(p => +p.hedgedVolume || 0).concat([0]));
  const step = pw / pts.length;
  const x = i => L + step * (i + .5);
  const y = v => T + (hi - v) * ph / (hi - lo);
  const vh = v => maxVol > 0 ? (+v || 0) / maxVol * ph * .38 : 0;

  // price grid: 4 lines
  let s = '';
  for (let g = 0; g <= 3; g++) {
    const v = lo + (hi - lo) * g / 3, yy = y(v).toFixed(1);
    s += '<line class="grid" x1="' + L + '" x2="' + (W - R) + '" y1="' + yy + '" y2="' + yy + '"/>' +
         '<text class="axis y" x="' + (L - 6) + '" y="' + (+yy + 4) + '">' + v.toFixed(Math.min(dec, 2)) + '</text>';
  }
  // month hit areas (hover / selected band)
  pts.forEach((p, i) => {
    s += '<rect class="month' + (p.month === props.selected ? ' selected' : '') + '" data-i="' + i + '" x="' + (L + step * i).toFixed(1) + '" y="' + T + '" width="' + step.toFixed(1) + '" height="' + ph + '" rx="4"/>';
  });
  // hedged volume columns (secondary scale, bottom)
  const cw = Math.min(22, step * .55);
  pts.forEach((p, i) => {
    const h = vh(p.hedgedVolume);
    if (h > 0) s += '<rect class="vol" x="' + (x(i) - cw / 2).toFixed(1) + '" y="' + (T + ph - h).toFixed(1) + '" width="' + cw.toFixed(1) + '" height="' + h.toFixed(1) + '" rx="2"/>';
  });
  // curve area, prior, curve
  const path = key => pts.map((p, i) => (i ? 'L' : 'M') + x(i).toFixed(1) + ' ' + y(+p[key]).toFixed(1)).join(' ');
  const d = path('price');
  s += '<path class="area" d="' + d + ' L' + x(pts.length - 1).toFixed(1) + ' ' + (T + ph) + ' L' + x(0).toFixed(1) + ' ' + (T + ph) + 'Z"/>';
  if (showPrior && pts.every(p => has(p.priorPrice))) s += '<path class="prior" d="' + path('priorPrice') + '"/>';
  s += '<path class="line" d="' + d + '"/>';
  // hedged price markers
  const hw = Math.min(16, step * .5);
  pts.forEach((p, i) => {
    if (has(p.hedgedPrice)) { const yy = y(+p.hedgedPrice).toFixed(1); s += '<line class="hedge" x1="' + (x(i) - hw / 2).toFixed(1) + '" x2="' + (x(i) + hw / 2).toFixed(1) + '" y1="' + yy + '" y2="' + yy + '"/>'; }
  });
  // dots and month labels (thinned when crowded)
  const every = step < 34 ? 2 : 1;
  pts.forEach((p, i) => {
    const sel = p.month === props.selected;
    s += '<circle class="dot' + (sel ? ' selected' : '') + '" cx="' + x(i).toFixed(1) + '" cy="' + y(+p.price).toFixed(1) + '" r="' + (sel ? 5 : 3.2) + '"/>';
    if (i % every === 0 || sel) s += '<text class="axis x" x="' + x(i).toFixed(1) + '" y="' + (H - 4) + '">' + esc(p.month) + '</text>';
  });
  plot.innerHTML = '<svg width="' + W + '" height="' + H + '">' + s + '</svg>';

  // hover tooltip and click
  plot.querySelectorAll('.month').forEach(el => {
    const i = +el.dataset.i, p = pts[i];
    el.onmouseenter = () => {
      tip.innerHTML = '<div class="tm">' + esc(p.month) + '</div>' +
        '<div class="tr">Price<b>' + num(p.price) + '</b></div>' +
        (showPrior ? '<div class="tr">Prior<b>' + num(p.priorPrice) + '</b></div>' : '') +
        '<div class="tr">Hedged price<b>' + (has(p.hedgedPrice) ? num(p.hedgedPrice) : '—') + '</b></div>' +
        '<div class="tr">Hedged volume<b>' + (has(p.hedgedVolume) ? vol(p.hedgedVolume) + ' ' + esc(props.volumeUnit || '') : '—') + '</b></div>';
      tip.style.display = 'block';
      const tw = tip.offsetWidth, th = tip.offsetHeight;
      let tx = x(i) + 12; if (tx + tw > W) tx = x(i) - 12 - tw;
      let ty = y(+p.price) - th / 2; ty = Math.max(0, Math.min(H - th, ty));
      tip.style.left = tx + 'px'; tip.style.top = ty + 'px';
    };
    el.onmouseleave = () => { tip.style.display = 'none'; };
    el.onclick = () => fire('monthSelected', { month: p.month });
  });

  legend.innerHTML = '<span class="k"><i></i>Curve</span>' +
    (showPrior ? '<span class="k"><i class="pr"></i>Prior</span>' : '') +
    '<span class="k"><i class="hp"></i>Hedged price</span>' +
    '<span class="k"><i class="hv"></i>Hedged volume' + (props.volumeUnit ? ' (' + esc(props.volumeUnit) + ')' : '') + '</span>';
}
